Span<T> getSpan(uint32_t Offset, uint32_t Size) const noexcept {
    uint32_t ByteSize = static_cast<uint32_t>(sizeof(T) * Size);
    if (unlikely(!checkAccessBound(Offset, ByteSize))) {
      return Span<T>();
    }
    return Span<T>(reinterpret_cast<T *>(&DataPtr[Offset]), Size);
  }

Span<T> getSpan(uint32_t Offset, uint32_t Count) const noexcept {
    uint32_t Size;
#if defined(_MSC_VER) && !defined(__clang__) 

    uint64_t Num =
        static_cast<uint64_t>(sizeof(T)) * static_cast<uint64_t>(Count);
    if ((Num >> 32) != 0) {
      return Span<T>();
    }
    Size = static_cast<uint32_t>(Num);
#else
    if (unlikely(__builtin_mul_overflow(static_cast<uint32_t>(sizeof(T)), Count,
                                        &Size))) {
      return Span<T>();
    }
#endif
    if (unlikely(!checkAccessBound(Offset, Size))) {
      return Span<T>();
    }
    return Span<T>(reinterpret_cast<T *>(&DataPtr[Offset]), Count);
  }

static int read_new_config_info (WavpackContext *wpc, WavpackMetadata *wpmd)
{
    int bytecnt = wpmd->byte_length;
    unsigned char *byteptr = wpmd->data;

    wpc->version_five = 1;      

    wpc->file_format = wpc->config.qmode = wpc->channel_layout = 0;

    if (wpc->channel_reordering) {
        free (wpc->channel_reordering);
        wpc->channel_reordering = NULL;
    }



    if (bytecnt) {
        wpc->file_format = *byteptr++;
        wpc->config.qmode = (wpc->config.qmode & ~0xff) | *byteptr++;
        bytecnt -= 2;



        if (bytecnt) {
            int nchans, i;

            wpc->channel_layout = (int32_t) *byteptr++ << 16;
            bytecnt--;



            if (bytecnt) {
                wpc->channel_layout += nchans = *byteptr++;
                bytecnt--;



                if (bytecnt) {
                    if (bytecnt > nchans)
                        return FALSE;

                    wpc->channel_reordering = malloc (nchans);



                    if (wpc->channel_reordering) {
                        for (i = 0; i < nchans; ++i)
                            if (bytecnt) {
                                wpc->channel_reordering [i] = *byteptr++;
                                bytecnt--;
                            }
                            else
                                wpc->channel_reordering [i] = i;
                    }
                }
            }
            else
                wpc->channel_layout += wpc->config.num_channels;
        }
    }

    return TRUE;
}

