void BalsaParser::MessageDone() {
  if (status_ == ParserStatus::Error) {
    return;
  }
  status_ = convertResult(connection_->onMessageComplete());
  if (!delay_reset_) {
    framer_.Reset();
  }
  first_byte_processed_ = false;
  headers_done_ = false;
}

void BalsaParser::MessageDone() {
  if (status_ == ParserStatus::Error ||


      (wait_for_first_byte_before_msg_done_ && !first_byte_processed_)) {
    return;
  }
  status_ = convertResult(connection_->onMessageComplete());
  if (!delay_reset_) {
    framer_.Reset();
  }
  first_byte_processed_ = false;
  headers_done_ = false;
}

