  return Data_Wrap_Struct(klass, NULL, deallocate, ctxt);
}

bool ChemDrawXMLFormat::EndElement(const string& name)
{

  if(name=="n")
  {
    _pmol->AddAtom(_tempAtom);
    atoms[_tempAtom.GetIdx()] = _pmol->NumAtoms();
    _tempAtom.Clear();
  }
  else if(name=="b")
  {
    _pmol->AddBond(Begin, End, Order, Flag);
	Order = -1;
  }
  else if(name=="fragment") 
  {
    EnsureEndElement();


    for (vector<unsigned int>::iterator vit = _handleImplicitHydrogens.begin();
         vit != _handleImplicitHydrogens.end(); ++vit)
           OBAtomAssignTypicalImplicitHydrogens(_pmol->GetAtom(atoms[*vit]));

    _pmol->EndModify();



    string MolFormula=_pmol->GetFormula();











    atoms.clear();
    return false;
  }















  return true;
}

