string transform3d::DescribeAsString() const
    {
      ostringstream r;
      int n, i, j;
      const matrix3x3 *m = static_cast <const matrix3x3 *> (this);
      const vector3 *v = static_cast <const vector3 *> (this);
      bool neg, first;
      for (i = 0; i < 3; i++)
        {
          if (i)
            r << ",";
          n = static_cast<int> (floor((*v)[i] * 12.0 + 0.1));
          j = 0;
          while ((*m)(i, j) == 0.)
            j++;
          neg = (*m)(i, j) < 0.;
          switch (n)
            {
              case 2:
                r << ((neg)? "1/6": "1/6+");
                break;
              case 3:
                r << ((neg)? "1/4": "1/4+");
                break;
              case 4:
                r << ((neg)? "1/3": "1/3+");
                break;
              case 6:
                r << ((neg)? "1/2": "1/2+");
                break;
              case 8:
                r << ((neg)? "2/3": "2/3+");
                break;
              case 9:
                r << ((neg)? "3/4": "3/4+");
                break;
              case 10:
                r << ((neg)? "5/6": "5/6+");
                break;
            }
            first = true;
            while (j < 3) {
              if ((*m)(i, j) != 0.)
                {
                  neg = (*m)(i, j) < 0.;
                  switch (j)
                    {
                      case 0:
                        r << ((neg)? "-x": (first? "x": "+x"));
                        break;
                     case 1:
                        r << ((neg)? "-y": (first? "y": "+y"));
                        break;
                     case 2:
                        r << ((neg)? "-z": (first? "z": "+z"));
                        break;
                    }
                  first = false;
                }
              j++;
            }
        }
      return r.str();
    }

string transform3d::DescribeAsString() const
    {
      ostringstream r;
      int n, i, j;
      const matrix3x3 *m = static_cast <const matrix3x3 *> (this);
      const vector3 *v = static_cast <const vector3 *> (this);
      bool neg, first;
      for (i = 0; i < 3; i++)
        {
          if (i)
            r << ",";
          n = static_cast<int> (floor((*v)[i] * 12.0 + 0.1));
          j = 0;
          while (j < 3 && (*m)(i, j) == 0.)
            j++;
          if (j >= 3)
            continue;
          neg = (*m)(i, j) < 0.;
          switch (n)
            {
              case 2:
                r << ((neg)? "1/6": "1/6+");
                break;
              case 3:
                r << ((neg)? "1/4": "1/4+");
                break;
              case 4:
                r << ((neg)? "1/3": "1/3+");
                break;
              case 6:
                r << ((neg)? "1/2": "1/2+");
                break;
              case 8:
                r << ((neg)? "2/3": "2/3+");
                break;
              case 9:
                r << ((neg)? "3/4": "3/4+");
                break;
              case 10:
                r << ((neg)? "5/6": "5/6+");
                break;
            }
            first = true;
            while (j < 3) {
              if ((*m)(i, j) != 0.)
                {
                  neg = (*m)(i, j) < 0.;
                  switch (j)
                    {
                      case 0:
                        r << ((neg)? "-x": (first? "x": "+x"));
                        break;
                     case 1:
                        r << ((neg)? "-y": (first? "y": "+y"));
                        break;
                     case 2:
                        r << ((neg)? "-z": (first? "z": "+z"));
                        break;
                    }
                  first = false;
                }
              j++;
            }
        }
      return r.str();
    }

static exr_result_t
undo_zip_impl (
    exr_decode_pipeline_t* decode,
    const void*            compressed_data,
    uint64_t               comp_buf_size,
    void*                  uncompressed_data,
    uint64_t               uncompressed_size,
    void*                  scratch_data,
    uint64_t               scratch_size)
{
    size_t       actual_out_bytes;
    exr_result_t res;

    if (scratch_size < uncompressed_size) return EXR_ERR_INVALID_ARGUMENT;

    res = exr_uncompress_buffer (
        decode->context,
        compressed_data,
        comp_buf_size,
        scratch_data,
        scratch_size,
        &actual_out_bytes);

    if (res == EXR_ERR_SUCCESS)
    {
        decode->bytes_decompressed = actual_out_bytes;
        if (comp_buf_size > actual_out_bytes)
            res = EXR_ERR_CORRUPT_CHUNK;
        else
            internal_zip_reconstruct_bytes (
                uncompressed_data, scratch_data, actual_out_bytes);
    }

    return res;
}

static exr_result_t
undo_zip_impl (
    exr_decode_pipeline_t* decode,
    const void*            compressed_data,
    uint64_t               comp_buf_size,
    void*                  uncompressed_data,
    uint64_t               uncompressed_size,
    void*                  scratch_data,
    uint64_t               scratch_size)
{
    size_t       actual_out_bytes;
    exr_result_t res;

    if (scratch_size < uncompressed_size) return EXR_ERR_INVALID_ARGUMENT;

    res = exr_uncompress_buffer (
        decode->context,
        compressed_data,
        comp_buf_size,
        scratch_data,
        scratch_size,
        &actual_out_bytes);

    if (res == EXR_ERR_SUCCESS)
    {
        decode->bytes_decompressed = actual_out_bytes;
        if (comp_buf_size > actual_out_bytes || actual_out_bytes > uncompressed_size)
            res = EXR_ERR_CORRUPT_CHUNK;
        else
            internal_zip_reconstruct_bytes (
                uncompressed_data, scratch_data, actual_out_bytes);
    }

    return res;
}

exr_result_t
exr_uncompress_buffer (
    exr_const_context_t ctxt,
    const void*         in,
    size_t              in_bytes,
    void*               out,
    size_t              out_bytes_avail,
    size_t*             actual_out)
{
    struct libdeflate_decompressor* decomp;
    enum libdeflate_result          res;
    size_t                          actual_in_bytes;
#ifdef EXR_USE_CONFIG_DEFLATE_STRUCT
    struct libdeflate_options opt = {
        .sizeof_options = sizeof (struct libdeflate_options),
        .malloc_func    = ctxt ? ctxt->alloc_fn : internal_exr_alloc,
        .free_func      = ctxt ? ctxt->free_fn : internal_exr_free};
#endif










#ifdef EXR_USE_CONFIG_DEFLATE_STRUCT
    decomp = libdeflate_alloc_decompressor_ex (&opt);
#else
    libdeflate_set_memory_allocator (
        ctxt ? ctxt->alloc_fn : internal_exr_alloc,
        ctxt ? ctxt->free_fn : internal_exr_free);
    decomp = libdeflate_alloc_decompressor ();
#endif
    if (decomp)
    {
        res = libdeflate_zlib_decompress_ex (
            decomp,
            in,
            in_bytes,
            out,
            out_bytes_avail,
            &actual_in_bytes,
            actual_out);

        libdeflate_free_decompressor (decomp);

        if (res == LIBDEFLATE_SUCCESS)
        {
            if (in_bytes == actual_in_bytes) return EXR_ERR_SUCCESS;

        }
        else if (res == LIBDEFLATE_INSUFFICIENT_SPACE)
        {
            return EXR_ERR_OUT_OF_MEMORY;
        }
        else if (res == LIBDEFLATE_SHORT_OUTPUT)
        {

            return EXR_ERR_SUCCESS;
        }
        return EXR_ERR_CORRUPT_CHUNK;
    }
    return EXR_ERR_OUT_OF_MEMORY;
}

