void
format_fractional_part_nsecs(gchar *buf, size_t buflen, guint32 nsecs, const char *decimal_point, int precision)
{
	gsize decimal_point_len;
	gint8 num_buf[CHARS_NANOSECONDS];
	gint8 *num_end = &num_buf[CHARS_NANOSECONDS];
	gint8 *num_ptr;
	size_t num_len;

	ws_assert(precision != 0);

	if (buflen == 0) {




		return;
	}




	decimal_point_len = g_strlcpy(buf, decimal_point, buflen);
	if (decimal_point_len >= buflen) {




		return;
	}
	buf += decimal_point_len;
	buflen -= decimal_point_len;
















	switch (precision) {

	case 1:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100000000, precision);
		break;

	case 2:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10000000, precision);
		break;

	case 3:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 1000000, precision);
		break;

	case 4:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100000, precision);
		break;

	case 5:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10000, precision);
		break;

	case 6:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 1000, precision);
		break;

	case 7:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100, precision);
		break;

	case 8:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10, precision);
		break;

	case 9:



		num_ptr = uint_to_str_back_len(num_end, nsecs,
		    precision);
		break;

	default:
		ws_assert_not_reached();
		break;
	}









	num_len = MIN((size_t)(num_end - num_ptr), buflen - 1);
	if (num_len == 0) {



		return;
	}




	memcpy(buf, num_ptr, num_len);




	*(buf + num_len) = '\0';
}

int
format_fractional_part_nsecs(gchar *buf, size_t buflen, guint32 nsecs, const char *decimal_point, int precision)
{
	gchar *ptr;
	size_t remaining;
	int num_bytes;
	gsize decimal_point_len;
	guint32 frac_part;
	gint8 num_buf[CHARS_NANOSECONDS];
	gint8 *num_end = &num_buf[CHARS_NANOSECONDS];
	gint8 *num_ptr;
	size_t num_len;

	ws_assert(precision != 0);

	if (buflen == 0) {




		return 0;
	}





	if (nsecs >= 1000000000U) {
		num_bytes = snprintf(buf, buflen, "%s(%u nanoseconds)",
		    decimal_point, nsecs);
		if ((unsigned int)num_bytes >= buflen) {







			return (int)(buflen - 1);
		}
		return num_bytes;
	}

	ptr = buf;
	remaining = buflen;
	num_bytes = 0;




	decimal_point_len = g_strlcpy(buf, decimal_point, buflen);
	if (decimal_point_len >= buflen) {







		return (int)(buflen - 1);
	}
	ptr += decimal_point_len;
	remaining -= decimal_point_len;
	num_bytes += decimal_point_len;
















	switch (precision) {

	case 1:



		frac_part = nsecs / 100000000U;
		break;

	case 2:



		frac_part = nsecs / 10000000U;
		break;

	case 3:



		frac_part = nsecs / 1000000U;
		break;

	case 4:



		frac_part = nsecs / 100000U;
		break;

	case 5:



		frac_part = nsecs / 10000U;
		break;

	case 6:



		frac_part = nsecs / 1000U;
		break;

	case 7:



		frac_part = nsecs / 100U;
		break;

	case 8:



		frac_part = nsecs / 10U;
		break;

	case 9:



		frac_part = nsecs;
		break;

	default:
		ws_assert_not_reached();
		break;
	}

	num_ptr = uint_to_str_back_len(num_end, frac_part, precision);









	num_len = MIN((size_t)(num_end - num_ptr), remaining - 1);
	if (num_len == 0) {




		return num_bytes;
	}




	memcpy(ptr, num_ptr, num_len);
	ptr += num_len;
	num_bytes += num_len;




	*ptr = '\0';
	return num_bytes;
}

static int
dissect_spoolss_keybuffer(tvbuff_t *tvb, int offset, packet_info *pinfo,
			  proto_tree *tree, dcerpc_info *di, guint8 *drep)
{
	guint32 size;
	int end_offset;

	if (di->conformant_run)
		return offset;



	offset = dissect_ndr_uint32(tvb, offset, pinfo, tree, di, drep,
				    hf_keybuffer_size, &size);

	end_offset = offset + (size*2);
	if (end_offset < offset) {





		end_offset = tvb_reported_length_remaining(tvb, offset) + 1;
	}

	while (offset < end_offset)
		offset = dissect_spoolss_uint16uni(
			tvb, offset, pinfo, tree, drep, NULL, hf_keybuffer);

	return offset;
}

static int
dissect_spoolss_keybuffer(tvbuff_t *tvb, int offset, packet_info *pinfo,
			  proto_tree *tree, dcerpc_info *di, guint8 *drep)
{
	guint32 size;
	int end_offset;

	if (di->conformant_run)
		return offset;



	offset = dissect_ndr_uint32(tvb, offset, pinfo, tree, di, drep,
				    hf_keybuffer_size, &size);

	end_offset = offset + (size*2);
	if (end_offset < offset) {





		end_offset = tvb_reported_length_remaining(tvb, offset) + 1;
	}

	while (offset > 0 && offset < end_offset) {
		offset = dissect_spoolss_uint16uni(
			tvb, offset, pinfo, tree, drep, NULL, hf_keybuffer);
	}

	return offset;
}

static int
dissect_spoolss_uint16uni(tvbuff_t *tvb, int offset, packet_info *pinfo _U_,
			  proto_tree *tree, guint8 *drep _U_, char **data,
			  int hf_name)
{
	gint len, remaining;
	char *text;

	if (offset % 2)
		offset += 2 - (offset % 2);



	remaining = tvb_captured_length_remaining(tvb, offset);
	if (remaining <= 0) {
		if (data)
			*data = g_strdup("");
		return offset;
	}

	text = tvb_get_string_enc(NULL, tvb, offset, remaining, ENC_UTF_16|ENC_LITTLE_ENDIAN);
	len = (int)strlen(text);

	proto_tree_add_string(tree, hf_name, tvb, offset, len * 2, text);

	if (data)
		*data = text;
	else
		g_free(text);

	return offset + (len + 1) * 2;
}

